import { RendererCanvas } from '../../../lib';

import { dataDefault, dataGuestCentered, dataWorkCentered } from './const';

interface AreaInput {
	name: string;
	width: number;
	length: number;
	color: number;
	isFixed?: boolean;
	relatedTo?: string[];
}

interface Point {
	x: number;
	y: number;
}
interface Rect extends Point {
	width: number;
	height: number;
}
interface PlacedArea extends Rect {
	name: string;
	color: string;
	isFixed?: boolean;
}
type EdgePosition = 'top' | 'right' | 'bottom' | 'left';

interface OptimizationMetrics {
	aspectRatioScore: number;
	utilizationScore: number;
	proximityScore: number;
	totalScore: number;
}

interface OptimizationResult {
	areas: AreaInput[];
	metrics: OptimizationMetrics;
	iteration: number;
}

class TreemapLayout {
	private areas: PlacedArea[] = [];

	constructor(
		private w: number,
		private h: number,
		private data: AreaInput[],
		private recPt: Point,
		private loadPt: Point,
	) {}

	private getRelation(a: AreaInput, b: AreaInput): number {
		if (!a.relatedTo || !b.relatedTo) return 0;
		const idxA = b.relatedTo.indexOf(a.name);
		const idxB = a.relatedTo.indexOf(b.name);
		return (idxA >= 0 ? 1 / (idxA + 1) : 0) + (idxB >= 0 ? 1 / (idxB + 1) : 0);
	}

	private sortByRelation(group: AreaInput[], anchor: string): AreaInput[] {
		return [...group].sort((a, b) => {
			const diffAnchor = this.getRelation(b, { name: anchor } as AreaInput) - this.getRelation(a, { name: anchor } as AreaInput);
			return Math.abs(diffAnchor) > 0.001 ? diffAnchor : this.getRelation(b, a) - this.getRelation(a, b);
		});
	}

	private getEdge(pt: Point): EdgePosition {
		const dists = [pt.y, this.h - pt.y, pt.x, this.w - pt.x];
		const edges: EdgePosition[] = ['top', 'bottom', 'left', 'right'];
		return edges[dists.indexOf(Math.min(...dists))];
	}

	private placeAtEdge(area: AreaInput, edge: EdgePosition): PlacedArea {
		const targetArea = area.width * area.length;
		const isVert = edge === 'left' || edge === 'right';
		const dim = isVert ? Math.sqrt(targetArea * (this.w / this.h)) : Math.sqrt(targetArea * (this.h / this.w));

		return {
			x: edge === 'right' ? this.w - dim : 0,
			y: edge === 'bottom' ? this.h - dim : 0,
			width: isVert ? dim : this.w,
			height: isVert ? this.h : dim,
			name: area.name,
			color: `#${area.color.toString(16).padStart(6, '0')}`,
			isFixed: true,
		};
	}

	private getAvailableRect(fixed: PlacedArea[], recEdge: EdgePosition, loadEdge: EdgePosition): Rect {
		let rect = { x: 0, y: 0, width: this.w, height: this.h };
		fixed.forEach((a) => {
			const edge = a.name === 'Reception' ? recEdge : loadEdge;
			if (edge === 'top') {
				rect.y += a.height;
				rect.height -= a.height;
			} else if (edge === 'bottom') rect.height -= a.height;
			else if (edge === 'left') {
				rect.x += a.width;
				rect.width -= a.width;
			} else rect.width -= a.width;
		});
		return rect;
	}

	private squarify(x: number, y: number, w: number, h: number, vals: number[], data: any[]) {
		if (vals.length === 0) return;

		const horiz = w >= h,
			side = horiz ? h : w;
		let sum = 0,
			worst = Infinity,
			cnt = 0;

		for (let i = 0; i < vals.length; i++) {
			const nextSum = sum + vals[i];
			const currWorst = this.getWorst(vals.slice(0, i + 1), side, nextSum);
			if (currWorst > worst) break;
			sum = nextSum;
			worst = currWorst;
			cnt++;
		}

		const thick = sum / side;
		let offset = 0;

		for (let i = 0; i < cnt; i++) {
			const len = vals[i] / thick;
			this.areas.push(horiz ? { x, y: y + offset, width: thick, height: len, ...data[i] } : { x: x + offset, y, width: len, height: thick, ...data[i] });
			offset += len;
		}

		if (horiz) this.squarify(x + thick, y, w - thick, h, vals.slice(cnt), data.slice(cnt));
		else this.squarify(x, y + thick, w, h - thick, vals.slice(cnt), data.slice(cnt));
	}

	private getWorst(row: number[], side: number, sum: number): number {
		const max = Math.max(...row),
			min = Math.min(...row);
		return Math.max((side ** 2 * max) / sum ** 2, sum ** 2 / (side ** 2 * min));
	}

	public calculate(): PlacedArea[] {
		this.areas = [];
		const recEdge = this.getEdge(this.recPt),
			loadEdge = this.getEdge(this.loadPt);
		const fixed: PlacedArea[] = [];

		const rec = this.data.find((a) => a.name === 'Reception');
		const load = this.data.find((a) => a.name === 'Loading Zone');
		if (rec) fixed.push(this.placeAtEdge(rec, recEdge));
		if (load) fixed.push(this.placeAtEdge(load, loadEdge));

		const flex = this.data.filter((a) => a.name !== 'Reception' && a.name !== 'Loading Zone');
		const groups = {
			reception: this.sortByRelation(
				flex.filter((a) => a.relatedTo?.includes('Reception')),
				'Reception',
			),
			loading: this.sortByRelation(
				flex.filter((a) => a.relatedTo?.includes('Loading Zone')),
				'Loading Zone',
			),
			others: flex.filter((a) => !a.relatedTo?.includes('Reception') && !a.relatedTo?.includes('Loading Zone')),
		};

		const availRect = this.getAvailableRect(fixed, recEdge, loadEdge);
		const totalArea = flex.reduce((s, a) => s + a.width * a.length, 0);
		const scale = (availRect.width * availRect.height) / totalArea;

		let { x, y, width, height } = availRect;
		[groups.reception, groups.loading, groups.others].forEach((grp) => {
			if (grp.length === 0) return;
			const gTotal = grp.reduce((s, a) => s + a.width * a.length * scale, 0);
			const horiz = width >= height;

			const [gx, gy, gw, gh] = horiz ? [x, y, gTotal / height, height] : [x, y, width, gTotal / width];

			if (horiz) {
				x += gw;
				width -= gw;
			} else {
				y += gh;
				height -= gh;
			}

			this.squarify(
				gx,
				gy,
				gw,
				gh,
				grp.map((d) => d.width * d.length * scale),
				grp.map((d) => ({ name: d.name, color: `#${d.color.toString(16).padStart(6, '0')}` })),
			);
		});

		return [...fixed, ...this.areas];
	}

	public getMetrics(): OptimizationMetrics {
		const aspectRatioScore =
			1 /
			(1 +
				this.areas.reduce((sum, a) => {
					const ratio = Math.max(a.width, a.height) / Math.min(a.width, a.height);
					return sum + Math.abs(ratio - 1);
				}, 0) /
					this.areas.length);

		const utilizationScore = this.areas.reduce((s, a) => s + a.width * a.height, 0) / (this.w * this.h);

		const calcCompactness = (group: PlacedArea[]) => {
			if (group.length === 0) return 0;
			const cx = group.reduce((s, a) => s + a.x + a.width / 2, 0) / group.length;
			const cy = group.reduce((s, a) => s + a.y + a.height / 2, 0) / group.length;
			const avgDist =
				group.reduce((s, a) => {
					const dx = a.x + a.width / 2 - cx;
					const dy = a.y + a.height / 2 - cy;
					return s + Math.sqrt(dx * dx + dy * dy);
				}, 0) / group.length;
			return 1 / (1 + avgDist / 100);
		};

		const recRelated = this.areas.filter((a) => a.name !== 'Reception' && this.data.find((d) => d.name === a.name)?.relatedTo?.includes('Reception'));
		const loadRelated = this.areas.filter((a) => a.name !== 'Loading Zone' && this.data.find((d) => d.name === a.name)?.relatedTo?.includes('Loading Zone'));
		const proximityScore = (calcCompactness(recRelated) + calcCompactness(loadRelated)) / 2;

		const totalScore = aspectRatioScore * 0.4 + utilizationScore * 0.3 + proximityScore * 0.3;

		return { aspectRatioScore, utilizationScore, proximityScore, totalScore };
	}
}

class SpaceOptimizer {
	private bestResult: OptimizationResult | null = null;
	private isOptimizing = false;

	constructor(
		private w: number,
		private h: number,
		private recPt: Point,
		private loadPt: Point,
	) {}

	public async optimize(initial: AreaInput[], iterations = 50, stepSize = 5, onProgress?: (p: number, r: OptimizationResult) => void): Promise<OptimizationResult> {
		this.isOptimizing = true;
		this.bestResult = null;

		const flex = initial.filter((a) => !a.isFixed);
		const fixed = initial.filter((a) => a.isFixed);

		for (let iter = 0; iter < iterations && this.isOptimizing; iter++) {
			const testAreas = [
				...fixed,
				...flex.map((a) => ({
					...a,
					width: Math.max(20, Math.min(300, a.width + (Math.random() - 0.5) * stepSize * 2)),
					length: Math.max(20, Math.min(200, a.length + (Math.random() - 0.5) * stepSize * 2)),
				})),
			];

			const layout = new TreemapLayout(this.w, this.h, testAreas, this.recPt, this.loadPt);
			layout.calculate();
			const metrics = layout.getMetrics();

			const result: OptimizationResult = { areas: testAreas, metrics, iteration: iter };

			if (!this.bestResult || metrics.totalScore > this.bestResult.metrics.totalScore) {
				this.bestResult = result;
			}

			if (onProgress) onProgress((iter + 1) / iterations, result);
			if (iter % 5 === 0) await new Promise((r) => setTimeout(r, 0));
		}

		this.isOptimizing = false;
		return this.bestResult!;
	}

	public stop() {
		this.isOptimizing = false;
	}
}

export class Solution {
	public divHost: HTMLElement;
	public renderer: Renderer;

	constructor(id: string) {
		this.divHost = document.getElementById(id);
		Object.assign(this.divHost.style, { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '15px', padding: '15px' });

		const ctrl = document.createElement('div');
		ctrl.style.cssText = 'width: 100%; max-width: 800px;';

		const canvas = document.createElement('div');
		canvas.id = 'canvas-container';
		// canvas.style.backgroundColor = '#555';

		this.divHost.append(ctrl, canvas);
		this.renderer = new Renderer(canvas, ctrl);
	}

	public destroy() {
		while (this.divHost?.firstChild) this.divHost.removeChild(this.divHost.firstChild);
	}
}

