function parseLLM(content: string) {
	const match = content.match(/\[[\s\S]*\]/);
	if (!match) throw new Error('No array found');

	const block = match[0];

	try {
		return JSON.parse(block); // JSON일 경우
	} catch {
		return new Function(`return ${block}`)(); // JS object일 경우
	}
}

